// Secure version of the application with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { checkSchema, validationResult } = require('express-validator');
const winston = require('winston');
const fs = require('fs');
const path = require('path');

const app = express();

// Create logs directory if it doesn't exist
const logDir = 'logs';
if (!fs.existsSync(logDir)) {
  fs.mkdirSync(logDir);
}

// Configure logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: path.join(logDir, 'error.log'), level: 'error' }),
    new winston.transports.File({ filename: path.join(logDir, 'combined.log') })
  ]
});

// Initialize security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'https://trusted-domain.com'
}));

// Configure rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({ error: 'Too many requests, please try again later.' });
  }
});

// Apply rate limiting to all requests
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.url} from ${req.ip}`);
  next();
});

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example of a secure endpoint with authentication and authorization
app.get('/users', (req, res) => {
  // In a real application, you would check authentication here
  // For example: if (!req.user || !req.user.isAdmin) { return res.status(403).json({ error: 'Unauthorized' }); }

  // Mock data - in a real app, this would come from a database
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example of a secure endpoint with input validation
app.get('/user/:id', 
  checkSchema({
    id: {
      in: ['params'],
      isInt: {
        options: { min: 1 }
      },
      toInt: true,
      errorMessage: 'User ID must be a positive integer'
    }
  }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real application, you would fetch user data from database here
    // For now, we'll return mock data
    res.json({ id: req.params.id, name: 'Mock User', email: 'mock@example.com' });
  }
);

// Centralized error handling
app.use((err, req, res, next) => {
  logger.error(`Error handling request: ${err.message}`, { stack: err.stack });

  // Don't expose sensitive error details in production
  const errorResponse = process.env.NODE_ENV === 'development'
    ? { error: err.message, stack: err.stack }
    : { error: 'Internal server error' };

  res.status(500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.url}`);
  res.status(404).json({ error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

