Here are immediate fixes you can apply to improve the security of `app.js`:

## 1. Fix Hardcoded Port Issue

**Current code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Fixed code:**
```javascript
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

**Environment variable:**
```
PORT=3000  # in .env file
```

## 2. Add Basic Security Headers

```javascript
const helmet = require('helmet');
app.use(helmet());
```

**Installation:**
```bash
npm install helmet
```

## 3. Add Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per 15 minutes
});

app.use(limiter);
```

**Installation:**
```bash
npm install express-rate-limit
```

## 4. Add Basic Authentication Middleware

```javascript
const simpleAuth = (req, res, next) => {
  const authHeader = req.headers['authorization'];

  // In production, use proper authentication
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Check if token is valid
  const token = authHeader.split(' ')[1];
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  next();
};

// Apply to sensitive endpoints
app.get('/users', simpleAuth, (req, res) => {
  // Your existing code
});
```

## 5. Add Error Handling Middleware

```javascript
// Error handling middleware should be last
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose details in production
  res.status(500).json({
    error: process.env.NODE_ENV === 'development' 
      ? err.message
      : 'Internal server error'
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
